    this.#uninstallHandlers()
    this.handlers = [ new MentionsAutocompleteHandler(this.element, this.urlValue) ]
  }

  #uninstallHandlers() {
    this.handlers.forEach(handler => handler.destroy())
    this.handlers = []
  }

  get editor() {
    return this.element.editor
